import React, { useState, useEffect } from "react";
import "./UserDashboard.css";

export default function UserDashboard() {
    const [checkIn, setCheckIn] = useState(null);
    const [checkOut, setCheckOut] = useState(null);
    const [timer, setTimer] = useState("00:00:00");
    const [history, setHistory] = useState([]);
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true); // Optional: show loader

    const [filter, setFilter] = useState("all");
    const [fromDate, setFromDate] = useState("");
    const [toDate, setToDate] = useState("");

    useEffect(() => {
        const userId = localStorage.getItem("userId");

        if (!userId) {
            window.location.href = "/login";
            return;
        }

        // Step 1: Try to load user from localStorage first (instant)
        const storedUser = localStorage.getItem("currentUser");
        if (storedUser) {
            setUser(JSON.parse(storedUser));
        }

        // Step 2: Always fetch fresh user data from backend
        const fetchUserData = async () => {
            try {
                const res = await fetch(`http://localhost:5000/api/user/${userId}`);
                if (!res.ok) throw new Error("Failed to fetch user");

                const userData = await res.json();
                setUser(userData);

                // Update localStorage so next time it's faster
                localStorage.setItem("currentUser", JSON.stringify(userData));
            } catch (err) {
                console.error("Error fetching user:", err);
                alert("Failed to load profile. Please log in again.");
                localStorage.clear();
                window.location.href = "/login";
            }
        };

        // Step 3: Fetch attendance history
        const fetchAttendance = async () => {
            try {
                const res = await fetch(`http://localhost:5000/api/attendance/${userId}`);
                if (!res.ok) throw new Error("Failed to fetch attendance");
                const data = await res.json();
                setHistory(data);
            } catch (err) {
                console.error("Error fetching attendance:", err);
            }
        };

        // Run both fetches
        Promise.all([fetchUserData(), fetchAttendance()]).finally(() => {
            setLoading(false);
        });

    }, []);

    // Timer logic
    useEffect(() => {
        let interval;
        if (checkIn && !checkOut) {
            interval = setInterval(() => {
                const now = new Date();
                const diff = now - checkIn;

                const hrs = String(Math.floor(diff / 3600000)).padStart(2, "0");
                const mins = String(Math.floor((diff % 3600000) / 60000)).padStart(2, "0");
                const secs = String(Math.floor((diff % 60000) / 1000)).padStart(2, "0");

                setTimer(`${hrs}:${mins}:${secs}`);
            }, 1000);
        }
        return () => clearInterval(interval);
    }, [checkIn, checkOut]);

    const handleCheckIn = () => {
        if (checkIn) return alert("Already checked in!");
        setCheckIn(new Date());
        setCheckOut(null);
        setTimer("00:00:00");
    };

    const handleCheckOut = () => {
        if (!checkIn) return alert("Check in first!");

        const now = new Date();
        const diffMs = now - checkIn;
        const diffHours = diffMs / (1000 * 60 * 60);

        if (diffHours < 9) {
            const remaining = 9 * 3600000 - diffMs;
            const hrs = Math.floor(remaining / 3600000);
            const mins = Math.floor((remaining % 3600000) / 60000);
            return alert(`Remaining: ${hrs}h ${mins}m to complete 9 hours`);
        }

        setCheckOut(now);

        const newEntry = {
            date: new Date().toISOString().split("T")[0],
            checkIn: checkIn.toLocaleTimeString(),
            checkOut: now.toLocaleTimeString(),
            hours: diffHours.toFixed(2),
        };

        setHistory(prev => [newEntry, ...prev]); // Add to top
    };

    const filteredHistory = history.filter((item) => {
        const itemDate = new Date(item.date);
        const today = new Date();

        if (filter === "today") {
            return itemDate.toDateString() === today.toDateString();
        }
        if (filter === "month") {
            return itemDate.getMonth() === today.getMonth() && itemDate.getFullYear() === today.getFullYear();
        }
        if (filter === "range" && fromDate && toDate) {
            const from = new Date(fromDate);
            const to = new Date(toDate);
            return itemDate >= from && itemDate <= to;
        }
        return true;
    });

    return (
        <div className="dashboard">
            {/* PROFILE */}
            <div className="profile-card">
                <img src="https://i.imgur.com/4Z7mK2K.png" alt="employee" />
                {loading ? (
                    <p>Loading profile...</p>
                ) : user ? (
                    <>
                        <h2>{user.name || "Employee"}</h2>
                        <p>{user.designation || "N/A"}</p>
                        <p className="id">{user.userId}</p>
                    </>
                ) : (
                    <p>No user data</p>
                )}

                <button
                    className="logout"
                    onClick={() => {
                        localStorage.clear();
                        window.location.href = "/login";
                    }}
                >
                    Logout
                </button>
            </div>

            {/* ATTENDANCE CARD */}
            <div className="attendance-card">
                <h3>Attendance Dashboard</h3>

                <div className="times">
                    <div>
                        <span>Check In</span>
                        <p>{checkIn ? checkIn.toLocaleTimeString() : "--:--"}</p>
                    </div>
                    <div>
                        <span>Check Out</span>
                        <p>{checkOut ? checkOut.toLocaleTimeString() : "--:--"}</p>
                    </div>
                    <div>
                        <span>Working Time</span>
                        <p>{timer}</p>
                    </div>
                </div>

                <div className="buttons">
                    <button onClick={handleCheckIn} disabled={!!checkIn}>
                        Check In
                    </button>
                    <button onClick={handleCheckOut} disabled={!checkIn || !!checkOut}>
                        Check Out
                    </button>
                </div>

                {/* FILTERS */}
                <div className="filters">
                    <button onClick={() => setFilter("all")} className={filter === "all" ? "active" : ""}>
                        All
                    </button>
                    <button onClick={() => setFilter("today")} className={filter === "today" ? "active" : ""}>
                        Today
                    </button>
                    <button onClick={() => setFilter("month")} className={filter === "month" ? "active" : ""}>
                        This Month
                    </button>

                    <div className="date-range">
                        <input type="date" value={fromDate} onChange={(e) => setFromDate(e.target.value)} />
                        <input type="date" value={toDate} onChange={(e) => setToDate(e.target.value)} />
                        <button onClick={() => setFilter("range")} disabled={!fromDate || !toDate}>
                            Apply
                        </button>
                    </div>
                </div>

                {/* HISTORY TABLE */}
                <table>
                    <thead>
                        <tr>
                            <th>Date</th>
                            <th>Check In</th>
                            <th>Check Out</th>
                            <th>Hours</th>
                        </tr>
                    </thead>
                    <tbody>
                        {filteredHistory.length > 0 ? (
                            filteredHistory.map((item, i) => (
                                <tr key={i}>
                                    <td>{item.date}</td>
                                    <td>{item.checkIn}</td>
                                    <td>{item.checkOut || "--"}</td>
                                    <td>{item.hours}</td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan="4">No records found</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
